(()=>{const pages={hero:['序 / 00','八卦大观','太极生两仪 · 两仪生四象 · 四象生八卦'],luopan:['壹 / 01','天池罗盘','观方位，识八象。后天八卦与二十四山。'],liushiya:['贰 / 02','六十四卦','八八相重，读卦辞，观爻变。'],yaogua:['叁 / 03','龟壳摇卦','三枚铜钱，六次成卦。保留易象原有三维摇卦体验。'],meihua:['肆 / 04','梅花生辰卦','以出生年月日与时辰，学习梅花易数起卦。']};const cover=document.getElementById('cover'),atlas=document.getElementById('atlas'),experience=document.getElementById('experience');let desiredMode='yao';function sendMode(){experience.contentWindow.postMessage({type:'yixiang-mode',mode:desiredMode},location.origin==='null'?'*':location.origin);}experience.addEventListener('load',sendMode);function route(){let key=location.hash.slice(1);if(!pages[key])key='hero';document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===key);if(a.dataset.page===key)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});['number','pageTitle','pageNote'].forEach((id,i)=>document.getElementById(id).textContent=pages[key][i]);document.body.classList.toggle('cover-page',key==='hero');const isAtlas=['hero','luopan','liushiya'].includes(key);cover.hidden=key!=='hero';atlas.hidden=!isAtlas||key==='hero';experience.hidden=isAtlas;if(isAtlas&&key!=='hero'){const hash='#'+key;try{if(atlas.contentWindow.location.hash!==hash)atlas.contentWindow.location.hash=hash;}catch{atlas.src='atlas/index.html'+hash;}}else if(!isAtlas){desiredMode=key==='meihua'?'meihua':'yao';if(!experience.getAttribute('src'))experience.src='experience.html?mode='+desiredMode;else sendMode();}window.scrollTo(0,0);}window.addEventListener('message',e=>{if(e.source===cover.contentWindow&&e.data?.type==='yixiang-cover-page'&&['luopan','liushiya','yaogua'].includes(e.data.page)){location.hash=e.data.page;return;}if(e.source===atlas.contentWindow&&e.data?.type==='yixiang-atlas-page'&&['hero','luopan','liushiya'].includes(e.data.page)){location.hash=e.data.page;return;}if(e.source!==experience.contentWindow)return;if(location.origin!=='null'&&e.origin!==location.origin)return;if(e.data?.type==='yixiang-mode-result'){const actual=e.data.mode==='meihua'?'meihua':'yaogua';if(['yaogua','meihua'].includes(location.hash.slice(1))&&location.hash.slice(1)!==actual)location.hash=actual;}});addEventListener('hashchange',route);route();})();